package com.nextfeet.nextfeet.service; import java.util.*; import org.springframework.stereotype.Service; import com.nextfeet.nextfeet.model.Usuario; import com.nextfeet.nextfeet.repository.UsuarioDAO; @Service public class UsuarioServiceImpl implements UsuarioService { private final UsuarioDAO dao; public UsuarioServiceImpl(UsuarioDAO dao){this.dao=dao;} public Usuario login(String c,String p){Usuario u=dao.buscarPorCorreo(c); return u!=null&&u.getPassword().equals(p)&&"ACTIVO".equals(u.getEstado())?u:null;} public Usuario obtener(Integer id){return dao.obtener(id);} public List<Usuario> listar(String r){return dao.listar(r);} public void registrar(Usuario u){u.setEstado("ACTIVO");dao.crear(u);} public void actualizar(Usuario u){dao.actualizar(u);} public void desactivar(Integer id){dao.cambiarEstado(id,"INACTIVO");} }